import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Acl Middleware","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/middleware/acl.md","filePath":"03-developer/middleware/acl.md"}`),a={name:`03-developer/middleware/acl.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="acl-middleware" tabindex="-1">Acl Middleware <a class="header-anchor" href="#acl-middleware" aria-label="Permalink to “Acl Middleware”">​</a></h1><p>This Middleware is responsible for controlling users&#39; access to various operations in the admin panel and serves as part of the project&#39;s Access Control Layer (ACL). Its purpose is to ensure that regular admin panel users can access only the sections and operations for which they have been granted the necessary permissions.</p><p>Based on the current Route name, this Middleware determines which section of the admin panel and which operation the request pertains to, then checks the user&#39;s access to that operation. If the user does not have the required permission, the request is stopped with a <code>403 Forbidden</code> error, and the requested operation cannot be executed.</p><p>Users with the <code>admin</code> or <code>developer</code> role are exempt from the usual access-level checks in this Middleware. For other users, access to administrative operations is checked against the permissions defined for their account. Sections such as <code>home</code> and <code>ckeditor</code> are also exempt from the usual operation access checks, so ACL restrictions are not applied to them.</p><p>In addition to checking access to regular operations, this Middleware also handles requests to bulk-delete data. For such requests, the user&#39;s access is checked against the permissions associated with the delete operation, preventing bulk operations from being executed without the appropriate permission.</p><p>If a user has no defined permissions, they are redirected to the admin panel&#39;s logout route. This behavior prevents users without permission to use the system&#39;s administrative sections from continuing to use them.</p><p>The core logic for defining and managing access is implemented in conjunction with the <code>Access</code> and <code>User</code> models. This Middleware uses the existing mechanisms for checking permissions and is responsible for enforcing access restrictions while processing admin panel requests. For details about the access structure, how permissions are assigned to users, and the Access Control Layer implementation, refer to the documentation for the <code>Access</code> and <code>User</code> models.</p><p><a href="./../../02-consumer/03-user-roles.html">03-user-roles.md</a><a href="./../models/access.html">access.md</a><a href="./../models/user.html">user.md</a></p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};